using Xunit;

namespace InvoiceApp.Tests;

public class ApprovalsControllerTests
{
    [Theory]
    [InlineData("Approver", "manager-reviewer", 50_000)]
    [InlineData("Admin", "director-reviewer", 500_000)]
    public void Approve_MapsSessionRoleToAuthorityAndRecordsUsername(
        string role,
        string username,
        decimal amount)
    {
        var invoice = PendingInvoice(amount);
        var repository = new FakeInvoiceRepository(invoice);
        var controller = ControllerFor(repository, new UserSession(username, role));

        var result = controller.Approve(invoice.Id);

        var approved = Assert.IsType<Invoice>(Assert.IsType<OkObjectResult>(result.Result).Value);
        Assert.Equal(InvoiceStatus.Approved, approved.Status);
        Assert.Equal(username, approved.DecidedBy);
        Assert.Equal(InvoiceStatus.Approved, repository.GetById(invoice.Id)?.Status);
        Assert.Equal(username, repository.GetById(invoice.Id)?.DecidedBy);
    }

    [Theory]
    [InlineData("Approver", "manager-reviewer", 50_001, "Invoice INV-1 amount 50,001 exceeds Manager approval limit of 50,000.")]
    [InlineData("Admin", "director-reviewer", 500_001, "Invoice INV-1 amount 500,001 exceeds Director single-approval limit of 500,000.")]
    public void Approve_OverLimitReturnsConflictAndPreservesInvoice(
        string role,
        string username,
        decimal amount,
        string expectedMessage)
    {
        var invoice = PendingInvoice(amount);
        invoice.DecidedBy = "previous-reviewer";
        invoice.DecisionNote = "previous note";
        var before = Snapshot(invoice);
        var repository = new FakeInvoiceRepository(invoice);
        var controller = ControllerFor(repository, new UserSession(username, role));

        var result = controller.Approve(invoice.Id);

        var conflict = Assert.IsType<ConflictObjectResult>(result.Result);
        Assert.Equal(StatusCodes.Status409Conflict, conflict.StatusCode);
        Assert.Equal(expectedMessage, ErrorMessage(conflict.Value));
        Assert.Equal(before, Snapshot(repository.GetById(invoice.Id)!));
    }

    private static ApprovalsController ControllerFor(FakeInvoiceRepository repository, UserSession session)
    {
        var controller = new ApprovalsController(new ApprovalService(repository));
        var httpContext = new DefaultHttpContext();
        httpContext.Items[HttpContextExtensions.SessionKey] = session;
        controller.ControllerContext = new ControllerContext { HttpContext = httpContext };
        return controller;
    }

    private static Invoice PendingInvoice(decimal amount) =>
        new() { Id = "INV-1", CustomerName = "Test School", Amount = amount, Status = InvoiceStatus.PendingApproval };

    private static string? ErrorMessage(object? value) =>
        value?.GetType().GetProperty("error")?.GetValue(value) as string;

    private static InvoiceSnapshot Snapshot(Invoice invoice) =>
        new(invoice.Id, invoice.CustomerName, invoice.Amount, invoice.Status, invoice.DecidedBy, invoice.DecidedAt, invoice.DecisionNote);

    private sealed record InvoiceSnapshot(
        string Id,
        string CustomerName,
        decimal Amount,
        InvoiceStatus Status,
        string? DecidedBy,
        DateTime? DecidedAt,
        string? DecisionNote);
}

using InvoiceApp.Api.Auth;
using InvoiceApp.Domain;
using Microsoft.AspNetCore.Mvc;

namespace InvoiceApp.Api.Controllers;

[ApiController]
[Route("api/[controller]")]
public class InvoicesController : ApiControllerBase
{
    private readonly IInvoiceRepository _repository;
    private readonly ApprovalService _approvals;

    public InvoicesController(IInvoiceRepository repository, ApprovalService approvals)
    {
        _repository = repository;
        _approvals = approvals;
    }

    public record CreateInvoiceRequest(string CustomerName, decimal Amount);

    [HttpGet]
    public ActionResult<IReadOnlyList<Invoice>> GetAll([FromQuery] string? status)
    {
        var invoices = _repository.GetAll();

        if (!string.IsNullOrEmpty(status))
        {
            if (!Enum.TryParse<InvoiceStatus>(status, ignoreCase: true, out var parsed))
            {
                return BadRequest(new { error = $"Unknown status '{status}'." });
            }

            invoices = invoices.Where(i => i.Status == parsed).ToList();
        }

        return Ok(invoices);
    }

    [HttpGet("{id}")]
    public ActionResult<Invoice> GetById(string id)
    {
        var invoice = _repository.GetById(id);
        return invoice is null ? NotFound() : Ok(invoice);
    }

    [HttpPost]
    public ActionResult<Invoice> Create([FromBody] CreateInvoiceRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.CustomerName))
        {
            return BadRequest(new { error = "Customer name is required." });
        }

        if (request.Amount <= 0)
        {
            return BadRequest(new { error = "Amount must be greater than zero." });
        }

        var invoice = _repository.Add(new Invoice
        {
            CustomerName = request.CustomerName.Trim(),
            Amount = request.Amount
        });

        return CreatedAtAction(nameof(GetById), new { id = invoice.Id }, invoice);
    }

    [HttpPost("{id}/submit")]
    public ActionResult<Invoice> Submit(string id) => Handle(() => _approvals.Submit(id));

    [HttpDelete("{id}")]
    [RequireRole("Admin")]
    public IActionResult Delete(string id) =>
        _repository.Remove(id) ? NoContent() : NotFound();
}

using InvoiceApp.Api.Auth;
using InvoiceApp.Domain;
using Microsoft.AspNetCore.Mvc;

namespace InvoiceApp.Api.Controllers;

[ApiController]
[Route("api/[controller]")]
[RequireRole("Approver", "Admin")]
public class ApprovalsController : ApiControllerBase
{
    private readonly ApprovalService _approvals;

    public ApprovalsController(ApprovalService approvals)
    {
        _approvals = approvals;
    }

    public record RejectRequest(string Reason);

    [HttpPost("{invoiceId}/approve")]
    public ActionResult<Invoice> Approve(string invoiceId) =>
        Handle(() =>
        {
            var session = HttpContext.GetSession();
            var authority = session.Role switch
            {
                "Approver" => ApprovalAuthority.Manager,
                "Admin" => ApprovalAuthority.Director,
                _ => throw new InvalidOperationException("This role has no invoice approval authority.")
            };

            return _approvals.Approve(invoiceId, session.Username, authority);
        });

    [HttpPost("{invoiceId}/reject")]
    public ActionResult<Invoice> Reject(string invoiceId, [FromBody] RejectRequest request) =>
        Handle(() => _approvals.Reject(invoiceId, HttpContext.GetSession().Username, request.Reason));
}

