namespace InvoiceApp.Tests;

internal class FakeInvoiceRepository : IInvoiceRepository
{
    private readonly List<Invoice> _invoices = new();

    public FakeInvoiceRepository(params Invoice[] seed) => _invoices.AddRange(seed);

    public IReadOnlyList<Invoice> GetAll() => _invoices.ToList();
    public Invoice? GetById(string id) => _invoices.FirstOrDefault(i => i.Id == id);
    public IReadOnlyList<Invoice> GetByIds(IEnumerable<string> ids) => _invoices.Where(i => ids.Contains(i.Id)).ToList();
    public Invoice Add(Invoice invoice) { _invoices.Add(invoice); return invoice; }
    public void Update(Invoice invoice) { }
    public bool Remove(string id) => _invoices.RemoveAll(i => i.Id == id) > 0;
}

using InvoiceApp.Domain;
using Xunit;

namespace InvoiceApp.Tests;

public class ApprovalServiceTests
{
    private sealed record InvoiceSnapshot(
        string Id,
        string CustomerName,
        decimal Amount,
        InvoiceStatus Status,
        DateTime CreatedAt,
        string? DecidedBy,
        DateTime? DecidedAt,
        string? DecisionNote);

    private static Invoice InvoiceWith(string id, InvoiceStatus status) =>
        new() { Id = id, CustomerName = "Test School", Amount = 100m, Status = status };

    private static ApprovalService ServiceFor(params Invoice[] invoices) =>
        new(new FakeInvoiceRepository(invoices));

    private static InvoiceSnapshot Snapshot(Invoice invoice) =>
        new(
            invoice.Id,
            invoice.CustomerName,
            invoice.Amount,
            invoice.Status,
            invoice.CreatedAt,
            invoice.DecidedBy,
            invoice.DecidedAt,
            invoice.DecisionNote);

    private static Invoice InvoiceWithDecisionHistory(string id, decimal amount) =>
        new()
        {
            Id = id,
            CustomerName = "Submitted Customer",
            Amount = amount,
            Status = InvoiceStatus.PendingApproval,
            CreatedAt = new DateTime(2020, 10, 30, 8, 15, 0, DateTimeKind.Utc),
            DecidedBy = "previous.actor",
            DecidedAt = new DateTime(2020, 10, 30, 9, 15, 0, DateTimeKind.Utc),
            DecisionNote = "previous decision note"
        };

    [Fact]
    public void Submit_MovesDraftToPendingApproval()
    {
        var invoice = InvoiceWith("INV-1", InvoiceStatus.Draft);

        var result = ServiceFor(invoice).Submit("INV-1");

        Assert.Equal(InvoiceStatus.PendingApproval, result.Status);
    }

    [Fact]
    public void Submit_RejectsInvoiceThatIsNotADraft()
    {
        var service = ServiceFor(InvoiceWith("INV-1", InvoiceStatus.Approved));

        Assert.Throws<InvalidOperationException>(() => service.Submit("INV-1"));
    }

    [Fact]
    public void Approve_SetsStatusApproverAndTimestamp()
    {
        var service = ServiceFor(InvoiceWith("INV-1", InvoiceStatus.PendingApproval));

        var result = service.Approve("INV-1", "[REDACTED]", ApprovalAuthority.Manager);

        Assert.Equal(InvoiceStatus.Approved, result.Status);
        Assert.Equal("[REDACTED]", result.DecidedBy);
        Assert.NotNull(result.DecidedAt);
    }

    [Fact]
    public void Approve_RejectsInvoiceThatIsStillADraft()
    {
        var invoice = InvoiceWith("INV-1", InvoiceStatus.Draft);
        var before = Snapshot(invoice);
        var service = ServiceFor(invoice);

        Assert.Throws<InvalidOperationException>(() =>
            service.Approve("INV-1", "[REDACTED]", ApprovalAuthority.Manager));

        Assert.Equal(before, Snapshot(invoice));
    }

    [Fact]
    public void Approve_ThrowsWhenInvoiceDoesNotExist()
    {
        var service = ServiceFor();

        Assert.Throws<KeyNotFoundException>(() =>
            service.Approve("INV-404", "[REDACTED]", ApprovalAuthority.Manager));
    }

    [Fact]
    public void Approve_ManagerAtLimit_ApprovesAndRecordsUsernameAsDecisionActor()
    {
        var invoice = InvoiceWith("INV-1", InvoiceStatus.PendingApproval);
        invoice.Amount = 50_000m;
        var service = ServiceFor(invoice);

        var result = service.Approve("INV-1", "reviewer-1", ApprovalAuthority.Manager);

        Assert.Equal(InvoiceStatus.Approved, result.Status);
        Assert.Equal("reviewer-1", result.DecidedBy);
        Assert.NotNull(result.DecidedAt);
    }

    [Fact]
    public void Approve_ManagerAboveLimit_DeniesWithoutChangingAnyInvoiceField()
    {
        const string expectedMessage =
            "Invoice INV-1 amount 50,001 exceeds Manager approval limit of 50,000.";
        var invoice = InvoiceWithDecisionHistory("INV-1", 50_001m);
        var before = Snapshot(invoice);
        var service = ServiceFor(invoice);

        var exception = Assert.Throws<InvalidOperationException>(() =>
            service.Approve("INV-1", "reviewer-1", ApprovalAuthority.Manager));

        Assert.Equal(expectedMessage, exception.Message);
        Assert.Equal(before, Snapshot(invoice));
    }

    [Theory]
    [InlineData(50_000)]
    [InlineData(500_000)]
    public void Approve_DirectorAtSpecifiedLimits_ApprovesAndRecordsUsernameAsDecisionActor(decimal amount)
    {
        var invoice = InvoiceWith("INV-1", InvoiceStatus.PendingApproval);
        invoice.Amount = amount;
        var service = ServiceFor(invoice);

        var result = service.Approve("INV-1", "reviewer-1", ApprovalAuthority.Director);

        Assert.Equal(InvoiceStatus.Approved, result.Status);
        Assert.Equal("reviewer-1", result.DecidedBy);
        Assert.NotNull(result.DecidedAt);
    }

    [Fact]
    public void Approve_DirectorBelowManagerLimit_Approves()
    {
        var invoice = InvoiceWith("INV-1", InvoiceStatus.PendingApproval);
        invoice.Amount = 49_999.99m;
        var service = ServiceFor(invoice);

        var result = service.Approve("INV-1", "reviewer-1", ApprovalAuthority.Director);

        Assert.Equal(InvoiceStatus.Approved, result.Status);
        Assert.Equal("reviewer-1", result.DecidedBy);
        Assert.NotNull(result.DecidedAt);
    }

    [Fact]
    public void Approve_DirectorAboveSingleApprovalLimit_DeniesWithoutChangingAnyInvoiceField()
    {
        const string expectedMessage =
            "Invoice INV-1 amount 500,001 exceeds Director single-approval limit of 500,000.";
        var invoice = InvoiceWithDecisionHistory("INV-1", 500_001m);
        var before = Snapshot(invoice);
        var service = ServiceFor(invoice);

        var exception = Assert.Throws<InvalidOperationException>(() =>
            service.Approve("INV-1", "reviewer-1", ApprovalAuthority.Director));

        Assert.Equal(expectedMessage, exception.Message);
        Assert.Equal(before, Snapshot(invoice));
    }

    [Fact]
    public void Reject_RecordsReasonAndApprover()
    {
        var invoice = InvoiceWithDecisionHistory("INV-1", 72_500m);
        var before = Snapshot(invoice);
        var service = ServiceFor(invoice);

        var result = service.Reject("INV-1", "[REDACTED]", "Duplicate invoice");

        Assert.Equal(InvoiceStatus.Rejected, result.Status);
        Assert.Equal("[REDACTED]", result.DecidedBy);
        Assert.NotNull(result.DecidedAt);
        Assert.NotEqual(before.DecidedAt, result.DecidedAt);
        Assert.Equal("Duplicate invoice", result.DecisionNote);
        Assert.Equal(
            before with
            {
                Status = InvoiceStatus.Rejected,
                DecidedBy = "[REDACTED]",
                DecidedAt = result.DecidedAt,
                DecisionNote = "Duplicate invoice"
            },
            Snapshot(invoice));
    }

    [Fact]
    public void Reject_RequiresAReason()
    {
        var service = ServiceFor(InvoiceWith("INV-1", InvoiceStatus.PendingApproval));

        Assert.Throws<ArgumentException>(() => service.Reject("INV-1", "[REDACTED]", "  "));
    }
}

using InvoiceApp.Api.Auth;
using InvoiceApp.Api.Controllers;
using InvoiceApp.Domain;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace InvoiceApp.Tests;

public class ApprovalsControllerTests
{
    [Theory]
    [InlineData("Approver", "manager-reviewer", 50_000)]
    [InlineData("Admin", "director-reviewer", 500_000)]
    public void Approve_MapsSessionRoleToAuthorityAndRecordsUsername(
        string role,
        string username,
        decimal amount)
    {
        var invoice = PendingInvoice(amount);
        var repository = new FakeInvoiceRepository(invoice);
        var controller = ControllerFor(repository, new UserSession(username, role));

        var result = controller.Approve(invoice.Id);

        var approved = Assert.IsType<Invoice>(Assert.IsType<OkObjectResult>(result.Result).Value);
        Assert.Equal(InvoiceStatus.Approved, approved.Status);
        Assert.Equal(username, approved.DecidedBy);
        Assert.Equal(InvoiceStatus.Approved, repository.GetById(invoice.Id)?.Status);
        Assert.Equal(username, repository.GetById(invoice.Id)?.DecidedBy);
    }

    [Theory]
    [InlineData("Approver", "manager-reviewer", 50_001, "Invoice INV-1 amount 50,001 exceeds Manager approval limit of 50,000.")]
    [InlineData("Admin", "director-reviewer", 500_001, "Invoice INV-1 amount 500,001 exceeds Director single-approval limit of 500,000.")]
    public void Approve_OverLimitReturnsConflictAndPreservesInvoice(
        string role,
        string username,
        decimal amount,
        string expectedMessage)
    {
        var invoice = PendingInvoice(amount);
        invoice.DecidedBy = "previous-reviewer";
        invoice.DecisionNote = "previous note";
        var before = Snapshot(invoice);
        var repository = new FakeInvoiceRepository(invoice);
        var controller = ControllerFor(repository, new UserSession(username, role));

        var result = controller.Approve(invoice.Id);

        var conflict = Assert.IsType<ConflictObjectResult>(result.Result);
        Assert.Equal(StatusCodes.Status409Conflict, conflict.StatusCode);
        Assert.Equal(expectedMessage, ErrorMessage(conflict.Value));
        Assert.Equal(before, Snapshot(repository.GetById(invoice.Id)!));
    }

    private static ApprovalsController ControllerFor(FakeInvoiceRepository repository, UserSession session)
    {
        var controller = new ApprovalsController(new ApprovalService(repository));
        var httpContext = new DefaultHttpContext();
        httpContext.Items[HttpContextExtensions.SessionKey] = session;
        controller.ControllerContext = new ControllerContext { HttpContext = httpContext };
        return controller;
    }

    private static Invoice PendingInvoice(decimal amount) =>
        new() { Id = "INV-1", CustomerName = "Test School", Amount = amount, Status = InvoiceStatus.PendingApproval };

    private static string? ErrorMessage(object? value) =>
        value?.GetType().GetProperty("error")?.GetValue(value) as string;

    private static InvoiceSnapshot Snapshot(Invoice invoice) =>
        new(
            invoice.Id,
            invoice.CustomerName,
            invoice.Amount,
            invoice.Status,
            invoice.CreatedAt,
            invoice.DecidedBy,
            invoice.DecidedAt,
            invoice.DecisionNote);

    private sealed record InvoiceSnapshot(
        string Id,
        string CustomerName,
        decimal Amount,
        InvoiceStatus Status,
        DateTime CreatedAt,
        string? DecidedBy,
        DateTime? DecidedAt,
        string? DecisionNote);
}

using InvoiceApp.Api.Auth;
using InvoiceApp.Domain;
using Microsoft.AspNetCore.Mvc;

namespace InvoiceApp.Api.Controllers;

[ApiController]
[Route("api/[controller]")]
[RequireRole("Approver", "Admin")]
public class ApprovalsController : ApiControllerBase
{
    private readonly ApprovalService _approvals;

    public ApprovalsController(ApprovalService approvals)
    {
        _approvals = approvals;
    }

    public record RejectRequest(string Reason);

    [HttpPost("{invoiceId}/approve")]
    public ActionResult<Invoice> Approve(string invoiceId) =>
        Handle(() =>
        {
            var session = HttpContext.GetSession();
            var authority = session.Role switch
            {
                "Approver" => ApprovalAuthority.Manager,
                "Admin" => ApprovalAuthority.Director,
                _ => throw new InvalidOperationException("This role has no invoice approval authority.")
            };

            return _approvals.Approve(invoiceId, session.Username, authority);
        });

    [HttpPost("{invoiceId}/reject")]
    public ActionResult<Invoice> Reject(string invoiceId, [FromBody] RejectRequest request) =>
        Handle(() => _approvals.Reject(invoiceId, HttpContext.GetSession().Username, request.Reason));
}

using InvoiceApp.Api.Auth;
using InvoiceApp.Domain;
using Microsoft.AspNetCore.Mvc;

namespace InvoiceApp.Api.Controllers;

[ApiController]
[Route("api/[controller]")]
public class InvoicesController : ApiControllerBase
{
    private readonly IInvoiceRepository _repository;
    private readonly ApprovalService _approvals;

    public InvoicesController(IInvoiceRepository repository, ApprovalService approvals)
    {
        _repository = repository;
        _approvals = approvals;
    }

    public record CreateInvoiceRequest(string CustomerName, decimal Amount);

    [HttpGet]
    public ActionResult<IReadOnlyList<Invoice>> GetAll([FromQuery] string? status)
    {
        var invoices = _repository.GetAll();

        if (!string.IsNullOrEmpty(status))
        {
            if (!Enum.TryParse<InvoiceStatus>(status, ignoreCase: true, out var parsed))
            {
                return BadRequest(new { error = $"Unknown status '{status}'." });
            }

            invoices = invoices.Where(i => i.Status == parsed).ToList();
        }

        return Ok(invoices);
    }

    [HttpGet("{id}")]
    public ActionResult<Invoice> GetById(string id)
    {
        var invoice = _repository.GetById(id);
        return invoice is null ? NotFound() : Ok(invoice);
    }

    [HttpPost]
    public ActionResult<Invoice> Create([FromBody] CreateInvoiceRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.CustomerName))
        {
            return BadRequest(new { error = "Customer name is required." });
        }

        if (request.Amount <= 0)
        {
            return BadRequest(new { error = "Amount must be greater than zero." });
        }

        var invoice = _repository.Add(new Invoice
        {
            CustomerName = request.CustomerName.Trim(),
            Amount = request.Amount
        });

        return CreatedAtAction(nameof(GetById), new { id = invoice.Id }, invoice);
    }

    [HttpPost("{id}/submit")]
    public ActionResult<Invoice> Submit(string id) => Handle(() => _approvals.Submit(id));

    [HttpDelete("{id}")]
    [RequireRole("Admin")]
    public IActionResult Delete(string id) =>
        _repository.Remove(id) ? NoContent() : NotFound();
}

(() => {
  const money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
  const $ = (id) => document.getElementById(id);
  let session = JSON.parse(sessionStorage.getItem('session') || 'null');

  function el(tag, attrs = {}, ...children) {
    const node = document.createElement(tag);
    for (const [key, value] of Object.entries(attrs)) {
      if (key === 'class') node.className = value;
      else node.setAttribute(key, value);
    }
    for (const child of children) node.append(child);
    return node;
  }

  async function api(path, options = {}) {
    const headers = { 'Content-Type': 'application/json', ...(options.headers || {}) };
    if (session) headers.[REDACTED] ${session.token}`;
    const response = await fetch(`/api${path}`, { ...options, headers });
    if (response.status === 401 && session) { signOut(); throw new Error('Session expired.'); }
    const body = response.status === 204 ? null : await response.json().catch(() => null);
    if (!response.ok) throw new Error((body && body.error) || `Request failed (${response.status})`);
    return body;
  }

  function show(id, visible) { $(id).hidden = !visible; }
  function showError(id, message) { const p = $(id); p.textContent = message || ''; p.hidden = !message; }

  function render() {
    const signedIn = !!session;
    show('login-view', !signedIn);
    show('app-view', signedIn);
    show('session-bar', signedIn);
    if (signedIn) {
      $('whoami').textContent = `${session.username} (${session.role})`;
      refresh();
    }
  }

  async function refresh() {
    const invoices = await api('/invoices');
    renderInvoices(invoices);
    renderPending(invoices.filter((i) => i.status === 'PendingApproval'));
  }

  function renderInvoices(invoices) {
    const body = $('invoices-table').querySelector('tbody');
    body.replaceChildren(...invoices.map((invoice) => {
      const actions = el('td');
      if (invoice.status === 'Draft') {
        const submit = el('button', { type: 'button', class: 'secondary', 'aria-label': `Submit invoice ${invoice.id} for approval` }, 'Submit for approval');
        submit.addEventListener('click', async () => { await api(`/invoices/${invoice.id}/submit`, { method: 'POST' }); refresh(); });
        actions.append(submit);
      }
      return el('tr', {},
        el('td', {}, invoice.id),
        el('td', {}, invoice.customerName),
        el('td', {}, money.format(invoice.amount)),
        el('td', { class: `status status-${invoice.status}` }, invoice.status.replace(/([a-z])([A-Z])/g, '$1 $2')),
        actions);
    }));
  }

  function renderPending(pending) {
    show('pending-empty', pending.length === 0);
    $('pending-list').replaceChildren(...pending.map((invoice) => {
      const reasonId = `reason-${invoice.id}`;
      const approve = el('button', { type: 'button', 'aria-label': `Approve invoice ${invoice.id}` }, 'Approve');
      const reject = el('button', { type: 'button', class: 'danger', 'aria-label': `Reject invoice ${invoice.id}` }, 'Reject');
      const reason = el('input', { id: reasonId, 'aria-label': `Rejection reason for ${invoice.id}`, placeholder: 'Reason (required to reject)' });

      approve.addEventListener('click', () => decide(`/approvals/${invoice.id}/approve`, {}));
      reject.addEventListener('click', () => decide(`/approvals/${invoice.id}/reject`, { reason: reason.value }));

      return el('li', {},
        el('span', {}, `${invoice.id} · ${invoice.customerName} · ${money.format(invoice.amount)}`),
        el('span', {}, approve),
        el('div', { class: 'reject-row' }, reason, reject));
    }));
  }

  async function decide(path, payload) {
    showError('decision-error', '');
    try {
      await api(path, { method: 'POST', body: JSON.stringify(payload) });
      await refresh();
    } catch (error) {
      showError('decision-error', error.message);
    }
  }

  function signOut() {
    if (session) api('/auth/logout', { method: 'POST' }).catch(() => {});
    session = null;
    sessionStorage.removeItem('session');
    render();
  }

  $('login-form').addEventListener('submit', async (event) => {
    event.preventDefault();
    showError('login-error', '');
    try {
      const result = await api('/auth/login', {
        method: 'POST',
        body: JSON.stringify({ username: $('username').value, [REDACTED] })
      });
      session = { [REDACTED], username: result.username, role: result.role };
      sessionStorage.setItem('session', JSON.stringify(session));
      $('password').value = '';
      render();
    } catch (error) {
      showError('login-error', error.message);
    }
  });

  $('new-invoice-form').addEventListener('submit', async (event) => {
    event.preventDefault();
    showError('create-error', '');
    try {
      await api('/invoices', {
        method: 'POST',
        body: JSON.stringify({ customerName: $('customer').value, amount: Number($('amount').value) })
      });
      $('new-invoice-form').reset();
      refresh();
    } catch (error) {
      showError('create-error', error.message);
    }
  });

  $('sign-out').addEventListener('click', signOut);

  for (const tab of ['invoices', 'approvals']) {
    $(`tab-${tab}`).addEventListener('click', () => {
      for (const other of ['invoices', 'approvals']) {
        $(`tab-${other}`).setAttribute('aria-selected', String(other === tab));
        show(`${other}-panel`, other === tab);
      }
    });
  }

  render();
})();

