namespace InvoiceApp.Api.Controllers;

public abstract class ApiControllerBase : ControllerBase
{
    /// <summary>Runs a service call and maps its failures to HTTP status codes.</summary>
    protected ActionResult<Invoice> Handle(Func<Invoice> action)
    {
        try
        {
            return Ok(action());
        }
        catch (KeyNotFoundException ex)
        {
            return NotFound(new { error = ex.Message });
        }
        catch (InvalidOperationException ex)
        {
            return Conflict(new { error = ex.Message });
        }
        catch (ArgumentException ex)
        {
            return BadRequest(new { error = ex.Message });
        }
    }
}

using InvoiceApp.Api.Auth;
using InvoiceApp.Domain;
using Microsoft.AspNetCore.Mvc;

namespace InvoiceApp.Api.Controllers;

[ApiController]
[Route("api/[controller]")]
public class InvoicesController : ApiControllerBase
{
    private readonly IInvoiceRepository _repository;
    private readonly ApprovalService _approvals;

    public InvoicesController(IInvoiceRepository repository, ApprovalService approvals)
    {
        _repository = repository;
        _approvals = approvals;
    }

    public record CreateInvoiceRequest(string CustomerName, decimal Amount);

    [HttpGet]
    public ActionResult<IReadOnlyList<Invoice>> GetAll([FromQuery] string? status)
    {
        var invoices = _repository.GetAll();

        if (!string.IsNullOrEmpty(status))
        {
            if (!Enum.TryParse<InvoiceStatus>(status, ignoreCase: true, out var parsed))
            {
                return BadRequest(new { error = $"Unknown status '{status}'." });
            }

            invoices = invoices.Where(i => i.Status == parsed).ToList();
        }

        return Ok(invoices);
    }

    [HttpGet("{id}")]
    public ActionResult<Invoice> GetById(string id)
    {
        var invoice = _repository.GetById(id);
        return invoice is null ? NotFound() : Ok(invoice);
    }

    [HttpPost]
    public ActionResult<Invoice> Create([FromBody] CreateInvoiceRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.CustomerName))
        {
            return BadRequest(new { error = "Customer name is required." });
        }

        if (request.Amount <= 0)
        {
            return BadRequest(new { error = "Amount must be greater than zero." });
        }

        var invoice = _repository.Add(new Invoice
        {
            CustomerName = request.CustomerName.Trim(),
            Amount = request.Amount
        });

        return CreatedAtAction(nameof(GetById), new { id = invoice.Id }, invoice);
    }

    [HttpPost("{id}/submit")]
    public ActionResult<Invoice> Submit(string id) => Handle(() => _approvals.Submit(id));

    [HttpDelete("{id}")]
    [RequireRole("Admin")]
    public IActionResult Delete(string id) =>
        _repository.Remove(id) ? NoContent() : NotFound();
}

using System.Globalization;

namespace InvoiceApp.Domain;

/// <summary>
/// Moves an invoice through its lifecycle: Draft -> PendingApproval -> Approved or Rejected.
/// One invoice at a time, decided as a whole by a single approver.
/// </summary>
public class ApprovalService
{
    private readonly IInvoiceRepository _repository;

    public ApprovalService(IInvoiceRepository repository)
    {
        _repository = repository;
    }

    public Invoice Submit(string invoiceId)
    {
        var invoice = Find(invoiceId);

        if (invoice.Status != InvoiceStatus.Draft)
        {
            throw new InvalidOperationException(
                $"Invoice {invoiceId} is {invoice.Status}; only drafts can be submitted.");
        }

        invoice.Status = InvoiceStatus.PendingApproval;
        _repository.Update(invoice);
        return invoice;
    }

    public Invoice Approve(string invoiceId, string approver, ApprovalAuthority authority)
    {
        var invoice = Find(invoiceId);
        EnsurePending(invoice);

        var (limit, limitDescription) = authority switch
        {
            ApprovalAuthority.Manager => (50_000m, "Manager approval limit"),
            ApprovalAuthority.Director => (500_000m, "Director single-approval limit"),
            _ => throw new ArgumentOutOfRangeException(nameof(authority), authority, "Unknown approval authority.")
        };

        if (invoice.Amount > limit)
        {
            var amount = invoice.Amount.ToString("#,##0.############################", CultureInfo.InvariantCulture);
            var formattedLimit = limit.ToString("#,##0.############################", CultureInfo.InvariantCulture);
            throw new InvalidOperationException(
                $"Invoice {invoiceId} amount {amount} exceeds {limitDescription} of {formattedLimit}.");
        }

        invoice.Status = InvoiceStatus.Approved;
        invoice.DecidedBy = approver;
        invoice.DecidedAt = DateTime.UtcNow;
        _repository.Update(invoice);
        return invoice;
    }

    public Invoice Approve(string invoiceId, string approver) =>
        Approve(invoiceId, approver, ApprovalAuthority.Manager);

    public Invoice Reject(string invoiceId, string approver, string reason)
    {
        if (string.IsNullOrWhiteSpace(reason))
        {
            throw new ArgumentException("A reason is required to reject an invoice.", nameof(reason));
        }

        var invoice = Find(invoiceId);
        EnsurePending(invoice);

        invoice.Status = InvoiceStatus.Rejected;
        invoice.DecidedBy = approver;
        invoice.DecidedAt = DateTime.UtcNow;
        invoice.DecisionNote = reason;
        _repository.Update(invoice);
        return invoice;
    }

    private Invoice Find(string invoiceId) =>
        _repository.GetById(invoiceId)
        ?? throw new KeyNotFoundException($"Invoice {invoiceId} was not found.");

    private static void EnsurePending(Invoice invoice)
    {
        if (invoice.Status != InvoiceStatus.PendingApproval)
        {
            throw new InvalidOperationException(
                $"Invoice {invoice.Id} is {invoice.Status}; only pending invoices can be decided.");
        }
    }
}

