using InvoiceApp.Domain;

namespace InvoiceApp.Api;

/// <summary>In-memory store so the demo app runs with no database. Seeded with a few invoices.</summary>
public class InMemoryInvoiceRepository : IAtomicInvoiceRepository
{
    private readonly object _lock = new();
    private int _nextNumber = 1006;

    private readonly List<Invoice> _invoices = new()
    {
        new Invoice { Id = "INV-1001", CustomerName = "Lakeside School District", Amount = 4250.00m, Status = InvoiceStatus.PendingApproval },
        new Invoice { Id = "INV-1002", CustomerName = "Hilltop Academy", Amount = 980.50m, Status = InvoiceStatus.PendingApproval },
        new Invoice { Id = "INV-1003", CustomerName = "Riverside Charter", Amount = 12300.00m, Status = InvoiceStatus.Approved, DecidedBy = "[REDACTED]", DecidedAt = DateTime.UtcNow.AddDays(-2) },
        new Invoice { Id = "INV-1004", CustomerName = "Oakwood Independent", Amount = 615.75m, Status = InvoiceStatus.PendingApproval },
        new Invoice { Id = "INV-1005", CustomerName = "Maple Grove Prep", Amount = 310.00m, Status = InvoiceStatus.Draft },
    };

    public IReadOnlyList<Invoice> GetAll()
    {
        lock (_lock) return _invoices.ToList();
    }

    public Invoice? GetById(string id)
    {
        lock (_lock) return _invoices.FirstOrDefault(i => i.Id == id);
    }

    public IReadOnlyList<Invoice> GetByIds(IEnumerable<string> ids)
    {
        var wanted = ids.ToHashSet();
        lock (_lock) return _invoices.Where(i => wanted.Contains(i.Id)).ToList();
    }

    public Invoice Add(Invoice invoice)
    {
        lock (_lock)
        {
            if (string.IsNullOrEmpty(invoice.Id))
            {
                invoice.Id = $"INV-{_nextNumber++}";
            }

            _invoices.Add(invoice);
            return invoice;
        }
    }

    public void Update(Invoice invoice)
    {
        lock (_lock)
        {
            var index = _invoices.FindIndex(i => i.Id == invoice.Id);
            if (index >= 0) _invoices[index] = invoice;
        }

        public T ExecuteAtomically<T>(string invoiceId, Func<Invoice?, T> transition)
        {
            ArgumentNullException.ThrowIfNull(transition);

            lock (_lock)
            {
                var index = _invoices.FindIndex(invoice => invoice.Id == invoiceId);
                if (index < 0)
                {
                    return transition(null);
                }

                var workingCopy = Copy(_invoices[index]);
                var result = transition(workingCopy);
                _invoices[index] = workingCopy;
                return result;
            }
        }

        private static Invoice Copy(Invoice invoice) =>
            new()
            {
                Id = invoice.Id,
                CustomerName = invoice.CustomerName,
                Amount = invoice.Amount,
                Status = invoice.Status,
                CreatedAt = invoice.CreatedAt,
                FirstApprovedBy = invoice.FirstApprovedBy,
                FirstApprovedAt = invoice.FirstApprovedAt,
                DecidedBy = invoice.DecidedBy,
                DecidedAt = invoice.DecidedAt,
                DecisionNote = invoice.DecisionNote
            };
    }

    public bool Remove(string id)
    {
        lock (_lock) return _invoices.RemoveAll(i => i.Id == id) > 0;
    }
}

using System.Globalization;

namespace InvoiceApp.Domain;

/// <summary>
/// Moves an invoice through its lifecycle: Draft -> PendingApproval -> Approved or Rejected.
/// One invoice at a time, decided as a whole by a single approver.
/// </summary>
public class ApprovalService
{
    private readonly IInvoiceRepository _repository;
    private readonly object _fallbackTransitionLock = new();

    public ApprovalService(IInvoiceRepository repository)
    {
        _repository = repository;
    }

    public Invoice Submit(string invoiceId)
    {
        var invoice = Find(invoiceId);

        if (invoice.Status != InvoiceStatus.Draft)
        {
            throw new InvalidOperationException(
                $"Invoice {invoiceId} is {invoice.Status}; only drafts can be submitted.");
        }

        invoice.Status = InvoiceStatus.PendingApproval;
        _repository.Update(invoice);
        return invoice;
    }

    public Invoice Approve(string invoiceId, string approver, ApprovalAuthority authority)
    {
        return Transition(invoiceId, invoice =>
        {
            EnsureKnownAuthority(authority);

            if (invoice.Status == InvoiceStatus.AwaitingSecondApproval)
            {
                if (authority != ApprovalAuthority.Director)
                {
                    throw new InvalidOperationException(
                        $"Only a Director may provide the second approval for invoice {invoiceId}.");
                }

                if (string.Equals(invoice.FirstApprovedBy, approver, StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        $"Invoice {invoiceId} requires a second approver different from the first approver.");
                }

                if (invoice.Amount <= 500_000m)
                {
                    throw new InvalidOperationException(
                        $"Invoice {invoiceId} is not eligible for a second approval because its amount does not exceed 500,000.");
                }

                invoice.Status = InvoiceStatus.Approved;
                invoice.DecidedBy = approver;
                invoice.DecidedAt = DateTime.UtcNow;
                return invoice;
            }

            EnsurePending(invoice);

            if (invoice.Amount > 500_000m)
            {
                invoice.Status = InvoiceStatus.AwaitingSecondApproval;
                invoice.FirstApprovedBy = approver;
                invoice.FirstApprovedAt = DateTime.UtcNow;
                return invoice;
            }

            var (limit, limitDescription) = authority switch
            {
                ApprovalAuthority.Manager => (50_000m, "Manager approval limit"),
                ApprovalAuthority.Director => (500_000m, "Director approval limit"),
                _ => throw new ArgumentOutOfRangeException(nameof(authority), authority, "Unknown approval authority.")
            };

            if (invoice.Amount > limit)
            {
                var amount = invoice.Amount.ToString("#,##0.############################", CultureInfo.InvariantCulture);
                var formattedLimit = limit.ToString("#,##0.############################", CultureInfo.InvariantCulture);
                throw new InvalidOperationException(
                    $"Invoice {invoiceId} amount {amount} exceeds {limitDescription} of {formattedLimit}.");
            }

            invoice.Status = InvoiceStatus.Approved;
            invoice.DecidedBy = approver;
            invoice.DecidedAt = DateTime.UtcNow;
            return invoice;
        });
    }

    public Invoice Approve(string invoiceId, string approver) =>
        Approve(invoiceId, approver, ApprovalAuthority.Manager);

    public Invoice Reject(string invoiceId, string approver, string reason)
    {
        if (string.IsNullOrWhiteSpace(reason))
        {
            throw new ArgumentException("A reason is required to reject an invoice.", nameof(reason));
        }

        return Transition(invoiceId, invoice =>
        {
            EnsurePending(invoice);

            invoice.Status = InvoiceStatus.Rejected;
            invoice.DecidedBy = approver;
            invoice.DecidedAt = DateTime.UtcNow;
            invoice.DecisionNote = reason;
            return invoice;
        });
    }

    private T Transition<T>(string invoiceId, Func<Invoice, T> transition)
    {
        if (_repository is IAtomicInvoiceRepository atomicRepository)
        {
            return atomicRepository.ExecuteAtomically(
                invoiceId,
                invoice => transition(invoice ?? throw new KeyNotFoundException($"Invoice {invoiceId} was not found.")));
        }

        lock (_fallbackTransitionLock)
        {
            var invoice = Find(invoiceId);
            var result = transition(invoice);
            _repository.Update(invoice);
            return result;
        }
    }

    private Invoice Find(string invoiceId) =>
        _repository.GetById(invoiceId)
        ?? throw new KeyNotFoundException($"Invoice {invoiceId} was not found.");

    private static void EnsurePending(Invoice invoice)
    {
        if (invoice.Status != InvoiceStatus.PendingApproval)
        {
            throw new InvalidOperationException(
                $"Invoice {invoice.Id} is {invoice.Status}; only pending invoices can be decided.");
        }

        private static void EnsureKnownAuthority(ApprovalAuthority authority)
        {
            if (authority is not ApprovalAuthority.Manager and not ApprovalAuthority.Director)
            {
                throw new ArgumentOutOfRangeException(nameof(authority), authority, "Unknown approval authority.");
            }
        }
    }
}

namespace InvoiceApp.Domain;

public interface IInvoiceRepository
{
    IReadOnlyList<Invoice> GetAll();
    Invoice? GetById(string id);
    IReadOnlyList<Invoice> GetByIds(IEnumerable<string> ids);
    Invoice Add(Invoice invoice);
    void Update(Invoice invoice);
    bool Remove(string id);
}

/// <summary>
/// Optional repository capability for serializing an invoice read/validate/write transition.
/// The callback receives an isolated working copy and it is persisted only if it returns normally.
/// </summary>
public interface IAtomicInvoiceRepository : IInvoiceRepository
{
    T ExecuteAtomically<T>(string invoiceId, Func<Invoice?, T> transition);
}

namespace InvoiceApp.Domain;

public class Invoice
{
    public string Id { get; set; } = string.Empty;
    public string CustomerName { get; set; } = string.Empty;
    public decimal Amount { get; set; }
    public InvoiceStatus Status { get; set; } = InvoiceStatus.Draft;
    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
    public string? FirstApprovedBy { get; set; }
    public DateTime? FirstApprovedAt { get; set; }
    public string? DecidedBy { get; set; }
    public DateTime? DecidedAt { get; set; }
    public string? DecisionNote { get; set; }
}

using InvoiceApp.Domain;
using Xunit;

namespace InvoiceApp.Tests;

public class ApprovalServiceTests
{
    private sealed record InvoiceSnapshot(
        string Id,
        string CustomerName,
        decimal Amount,
        InvoiceStatus Status,
        DateTime CreatedAt,
        string? DecidedBy,
        DateTime? DecidedAt,
        string? DecisionNote);

    private static Invoice InvoiceWith(string id, InvoiceStatus status) =>
        new() { Id = id, CustomerName = "Test School", Amount = 100m, Status = status };

    private static ApprovalService ServiceFor(params Invoice[] invoices) =>
        new(new FakeInvoiceRepository(invoices));

    private static InvoiceSnapshot Snapshot(Invoice invoice) =>
        new(
            invoice.Id,
            invoice.CustomerName,
            invoice.Amount,
            invoice.Status,
            invoice.CreatedAt,
            invoice.DecidedBy,
            invoice.DecidedAt,
            invoice.DecisionNote);

    private static Invoice InvoiceWithDecisionHistory(string id, decimal amount) =>
        new()
        {
            Id = id,
            CustomerName = "Submitted Customer",
            Amount = amount,
            Status = InvoiceStatus.PendingApproval,
            CreatedAt = new DateTime(2020, 10, 30, 8, 15, 0, DateTimeKind.Utc),
            DecidedBy = "previous.actor",
            DecidedAt = new DateTime(2020, 10, 30, 9, 15, 0, DateTimeKind.Utc),
            DecisionNote = "previous decision note"
        };

    [Fact]
    public void Submit_MovesDraftToPendingApproval()
    {
        var invoice = InvoiceWith("INV-1", InvoiceStatus.Draft);

        var result = ServiceFor(invoice).Submit("INV-1");

        Assert.Equal(InvoiceStatus.PendingApproval, result.Status);
    }

    [Fact]
    public void Submit_RejectsInvoiceThatIsNotADraft()
    {
        var service = ServiceFor(InvoiceWith("INV-1", InvoiceStatus.Approved));

        Assert.Throws<InvalidOperationException>(() => service.Submit("INV-1"));
    }

    [Fact]
    public void Approve_SetsStatusApproverAndTimestamp()
    {
        var service = ServiceFor(InvoiceWith("INV-1", InvoiceStatus.PendingApproval));

        var result = service.Approve("INV-1", "[REDACTED]", ApprovalAuthority.Manager);

        Assert.Equal(InvoiceStatus.Approved, result.Status);
        Assert.Equal("[REDACTED]", result.DecidedBy);
        Assert.NotNull(result.DecidedAt);
    }

    [Fact]
    public void Approve_RejectsInvoiceThatIsStillADraft()
    {
        var invoice = InvoiceWith("INV-1", InvoiceStatus.Draft);
        var before = Snapshot(invoice);
        var service = ServiceFor(invoice);

        Assert.Throws<InvalidOperationException>(() =>
            service.Approve("INV-1", "[REDACTED]", ApprovalAuthority.Manager));

        Assert.Equal(before, Snapshot(invoice));
    }

    [Fact]
    public void Approve_ThrowsWhenInvoiceDoesNotExist()
    {
        var service = ServiceFor();

        Assert.Throws<KeyNotFoundException>(() =>
            service.Approve("INV-404", "[REDACTED]", ApprovalAuthority.Manager));
    }

    [Fact]
    public void Approve_ManagerAtLimit_ApprovesAndRecordsUsernameAsDecisionActor()
    {
        var invoice = InvoiceWith("INV-1", InvoiceStatus.PendingApproval);
        invoice.Amount = 50_000m;
        var service = ServiceFor(invoice);

        var result = service.Approve("INV-1", "reviewer-1", ApprovalAuthority.Manager);

        Assert.Equal(InvoiceStatus.Approved, result.Status);
        Assert.Equal("reviewer-1", result.DecidedBy);
        Assert.NotNull(result.DecidedAt);
    }

    [Fact]
    public void Approve_ManagerAboveLimit_DeniesWithoutChangingAnyInvoiceField()
    {
        const string expectedMessage =
            "Invoice INV-1 amount 50,001 exceeds Manager approval limit of 50,000.";
        var invoice = InvoiceWithDecisionHistory("INV-1", 50_001m);
        var before = Snapshot(invoice);
        var service = ServiceFor(invoice);

        var exception = Assert.Throws<InvalidOperationException>(() =>
            service.Approve("INV-1", "reviewer-1", ApprovalAuthority.Manager));

        Assert.Equal(expectedMessage, exception.Message);
        Assert.Equal(before, Snapshot(invoice));
    }

    [Theory]
    [InlineData(50_000)]
    [InlineData(500_000)]
    public void Approve_DirectorAtSpecifiedLimits_ApprovesAndRecordsUsernameAsDecisionActor(decimal amount)
    {
        var invoice = InvoiceWith("INV-1", InvoiceStatus.PendingApproval);
        invoice.Amount = amount;
        var service = ServiceFor(invoice);

        var result = service.Approve("INV-1", "reviewer-1", ApprovalAuthority.Director);

        Assert.Equal(InvoiceStatus.Approved, result.Status);
        Assert.Equal("reviewer-1", result.DecidedBy);
        Assert.NotNull(result.DecidedAt);
    }

    [Fact]
    public void Approve_DirectorBelowManagerLimit_Approves()
    {
        var invoice = InvoiceWith("INV-1", InvoiceStatus.PendingApproval);
        invoice.Amount = 49_999.99m;
        var service = ServiceFor(invoice);

        var result = service.Approve("INV-1", "reviewer-1", ApprovalAuthority.Director);

        Assert.Equal(InvoiceStatus.Approved, result.Status);
        Assert.Equal("reviewer-1", result.DecidedBy);
        Assert.NotNull(result.DecidedAt);
    }

    [Fact]
    public void Approve_DirectorAboveSingleApprovalLimit_DeniesWithoutChangingAnyInvoiceField()
    {
        const string expectedMessage =
            "Invoice INV-1 amount 500,001 exceeds Director single-approval limit of 500,000.";
        var invoice = InvoiceWithDecisionHistory("INV-1", 500_001m);
        var before = Snapshot(invoice);
        var service = ServiceFor(invoice);

        var exception = Assert.Throws<InvalidOperationException>(() =>
            service.Approve("INV-1", "reviewer-1", ApprovalAuthority.Director));

        Assert.Equal(expectedMessage, exception.Message);
        Assert.Equal(before, Snapshot(invoice));
    }

    [Fact]
    public void Reject_RecordsReasonAndApprover()
    {
        var invoice = InvoiceWithDecisionHistory("INV-1", 72_500m);
        var before = Snapshot(invoice);
        var service = ServiceFor(invoice);

        var result = service.Reject("INV-1", "[REDACTED]", "Duplicate invoice");

        Assert.Equal(InvoiceStatus.Rejected, result.Status);
        Assert.Equal("[REDACTED]", result.DecidedBy);
        Assert.NotNull(result.DecidedAt);
        Assert.NotEqual(before.DecidedAt, result.DecidedAt);
        Assert.Equal("Duplicate invoice", result.DecisionNote);
        Assert.Equal(
            before with
            {
                Status = InvoiceStatus.Rejected,
                DecidedBy = "[REDACTED]",
                DecidedAt = result.DecidedAt,
                DecisionNote = "Duplicate invoice"
            },
            Snapshot(invoice));
    }

    [Fact]
    public void Reject_RequiresAReason()
    {
        var service = ServiceFor(InvoiceWith("INV-1", InvoiceStatus.PendingApproval));

        Assert.Throws<ArgumentException>(() => service.Reject("INV-1", "[REDACTED]", "  "));
    }
}

