using InvoiceApp.Domain;
using Xunit;

namespace InvoiceApp.Tests;

public class ApprovalServiceTests
{
    private sealed record InvoiceSnapshot(
        string Id,
        string CustomerName,
        decimal Amount,
        InvoiceStatus Status,
        DateTime CreatedAt,
        string? DecidedBy,
        DateTime? DecidedAt,
        string? DecisionNote);

    private static Invoice InvoiceWith(string id, InvoiceStatus status) =>
        new() { Id = id, CustomerName = "Test School", Amount = 100m, Status = status };

    private static ApprovalService ServiceFor(params Invoice[] invoices) =>
        new(new FakeInvoiceRepository(invoices));

    private static InvoiceSnapshot Snapshot(Invoice invoice) =>
        new(
            invoice.Id,
            invoice.CustomerName,
            invoice.Amount,
            invoice.Status,
            invoice.CreatedAt,
            invoice.DecidedBy,
            invoice.DecidedAt,
            invoice.DecisionNote);

    private static Invoice InvoiceWithDecisionHistory(string id, decimal amount) =>
        new()
        {
            Id = id,
            CustomerName = "Submitted Customer",
            Amount = amount,
            Status = InvoiceStatus.PendingApproval,
            CreatedAt = new DateTime(2020, 10, 30, 8, 15, 0, DateTimeKind.Utc),
            DecidedBy = "previous.actor",
            DecidedAt = new DateTime(2020, 10, 30, 9, 15, 0, DateTimeKind.Utc),
            DecisionNote = "previous decision note"
        };

    [Fact]
    public void Submit_MovesDraftToPendingApproval()
    {
        var invoice = InvoiceWith("INV-1", InvoiceStatus.Draft);

        var result = ServiceFor(invoice).Submit("INV-1");

        Assert.Equal(InvoiceStatus.PendingApproval, result.Status);
    }

    [Fact]
    public void Submit_RejectsInvoiceThatIsNotADraft()
    {
        var service = ServiceFor(InvoiceWith("INV-1", InvoiceStatus.Approved));

        Assert.Throws<InvalidOperationException>(() => service.Submit("INV-1"));
    }

    [Fact]
    public void Approve_SetsStatusApproverAndTimestamp()
    {
        var service = ServiceFor(InvoiceWith("INV-1", InvoiceStatus.PendingApproval));

        var result = service.Approve("INV-1", "[REDACTED]", ApprovalAuthority.Manager);

        Assert.Equal(InvoiceStatus.Approved, result.Status);
        Assert.Equal("[REDACTED]", result.DecidedBy);
        Assert.NotNull(result.DecidedAt);
    }

    [Fact]
    public void Approve_RejectsInvoiceThatIsStillADraft()
    {
        var invoice = InvoiceWith("INV-1", InvoiceStatus.Draft);
        var before = Snapshot(invoice);
        var service = ServiceFor(invoice);

        Assert.Throws<InvalidOperationException>(() =>
            service.Approve("INV-1", "[REDACTED]", ApprovalAuthority.Manager));

        Assert.Equal(before, Snapshot(invoice));
    }

    [Fact]
    public void Approve_ThrowsWhenInvoiceDoesNotExist()
    {
        var service = ServiceFor();

        Assert.Throws<KeyNotFoundException>(() =>
            service.Approve("INV-404", "[REDACTED]", ApprovalAuthority.Manager));
    }

    [Fact]
    public void Approve_ManagerAtLimit_ApprovesAndRecordsUsernameAsDecisionActor()
    {
        var invoice = InvoiceWith("INV-1", InvoiceStatus.PendingApproval);
        invoice.Amount = 50_000m;
        var service = ServiceFor(invoice);

        var result = service.Approve("INV-1", "reviewer-1", ApprovalAuthority.Manager);

        Assert.Equal(InvoiceStatus.Approved, result.Status);
        Assert.Equal("reviewer-1", result.DecidedBy);
        Assert.NotNull(result.DecidedAt);
    }

    [Fact]
    public void Approve_ManagerAboveLimit_DeniesWithoutChangingAnyInvoiceField()
    {
        const string expectedMessage =
            "Invoice INV-1 amount 50,001 exceeds Manager approval limit of 50,000.";
        var invoice = InvoiceWithDecisionHistory("INV-1", 50_001m);
        var before = Snapshot(invoice);
        var service = ServiceFor(invoice);

        var exception = Assert.Throws<InvalidOperationException>(() =>
            service.Approve("INV-1", "reviewer-1", ApprovalAuthority.Manager));

        Assert.Equal(expectedMessage, exception.Message);
        Assert.Equal(before, Snapshot(invoice));
    }

    [Theory]
    [InlineData(50_000)]
    [InlineData(500_000)]
    public void Approve_DirectorAtSpecifiedLimits_ApprovesAndRecordsUsernameAsDecisionActor(decimal amount)
    {
        var invoice = InvoiceWith("INV-1", InvoiceStatus.PendingApproval);
        invoice.Amount = amount;
        var service = ServiceFor(invoice);

        var result = service.Approve("INV-1", "reviewer-1", ApprovalAuthority.Director);

        Assert.Equal(InvoiceStatus.Approved, result.Status);
        Assert.Equal("reviewer-1", result.DecidedBy);
        Assert.NotNull(result.DecidedAt);
    }

    [Fact]
    public void Approve_DirectorBelowManagerLimit_Approves()
    {
        var invoice = InvoiceWith("INV-1", InvoiceStatus.PendingApproval);
        invoice.Amount = 49_999.99m;
        var service = ServiceFor(invoice);

        var result = service.Approve("INV-1", "reviewer-1", ApprovalAuthority.Director);

        Assert.Equal(InvoiceStatus.Approved, result.Status);
        Assert.Equal("reviewer-1", result.DecidedBy);
        Assert.NotNull(result.DecidedAt);
    }

    [Fact]
    public void Approve_DirectorAboveSingleApprovalLimit_DeniesWithoutChangingAnyInvoiceField()
    {
        const string expectedMessage =
            "Invoice INV-1 amount 500,001 exceeds Director single-approval limit of 500,000.";
        var invoice = InvoiceWithDecisionHistory("INV-1", 500_001m);
        var before = Snapshot(invoice);
        var service = ServiceFor(invoice);

        var exception = Assert.Throws<InvalidOperationException>(() =>
            service.Approve("INV-1", "reviewer-1", ApprovalAuthority.Director));

        Assert.Equal(expectedMessage, exception.Message);
        Assert.Equal(before, Snapshot(invoice));
    }

    [Fact]
    public void Reject_RecordsReasonAndApprover()
    {
        var invoice = InvoiceWithDecisionHistory("INV-1", 72_500m);
        var before = Snapshot(invoice);
        var service = ServiceFor(invoice);

        var result = service.Reject("INV-1", "[REDACTED]", "Duplicate invoice");

        Assert.Equal(InvoiceStatus.Rejected, result.Status);
        Assert.Equal("[REDACTED]", result.DecidedBy);
        Assert.NotNull(result.DecidedAt);
        Assert.NotEqual(before.DecidedAt, result.DecidedAt);
        Assert.Equal("Duplicate invoice", result.DecisionNote);
        Assert.Equal(
            before with
            {
                Status = InvoiceStatus.Rejected,
                DecidedBy = "[REDACTED]",
                DecidedAt = result.DecidedAt,
                DecisionNote = "Duplicate invoice"
            },
            Snapshot(invoice));
    }

    [Fact]
    public void Reject_RequiresAReason()
    {
        var service = ServiceFor(InvoiceWith("INV-1", InvoiceStatus.PendingApproval));

        Assert.Throws<ArgumentException>(() => service.Reject("INV-1", "[REDACTED]", "  "));
    }
}

using InvoiceApp.Api.Auth;
using InvoiceApp.Api.Controllers;
using InvoiceApp.Domain;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace InvoiceApp.Tests;

public class ApprovalsControllerTests
{
    [Theory]
    [InlineData("Approver", "manager-reviewer", 50_000)]
    [InlineData("Admin", "director-reviewer", 500_000)]
    public void Approve_MapsSessionRoleToAuthorityAndRecordsUsername(
        string role,
        string username,
        decimal amount)
    {
        var invoice = PendingInvoice(amount);
        var repository = new FakeInvoiceRepository(invoice);
        var controller = ControllerFor(repository, new UserSession(username, role));

        var result = controller.Approve(invoice.Id);

        var approved = Assert.IsType<Invoice>(Assert.IsType<OkObjectResult>(result.Result).Value);
        Assert.Equal(InvoiceStatus.Approved, approved.Status);
        Assert.Equal(username, approved.DecidedBy);
        Assert.Equal(InvoiceStatus.Approved, repository.GetById(invoice.Id)?.Status);
        Assert.Equal(username, repository.GetById(invoice.Id)?.DecidedBy);
    }

    [Theory]
    [InlineData("Approver", "manager-reviewer", 50_001, "Invoice INV-1 amount 50,001 exceeds Manager approval limit of 50,000.")]
    [InlineData("Admin", "director-reviewer", 500_001, "Invoice INV-1 amount 500,001 exceeds Director single-approval limit of 500,000.")]
    public void Approve_OverLimitReturnsConflictAndPreservesInvoice(
        string role,
        string username,
        decimal amount,
        string expectedMessage)
    {
        var invoice = PendingInvoice(amount);
        invoice.DecidedBy = "previous-reviewer";
        invoice.DecisionNote = "previous note";
        var before = Snapshot(invoice);
        var repository = new FakeInvoiceRepository(invoice);
        var controller = ControllerFor(repository, new UserSession(username, role));

        var result = controller.Approve(invoice.Id);

        var conflict = Assert.IsType<ConflictObjectResult>(result.Result);
        Assert.Equal(StatusCodes.Status409Conflict, conflict.StatusCode);
        Assert.Equal(expectedMessage, ErrorMessage(conflict.Value));
        Assert.Equal(before, Snapshot(repository.GetById(invoice.Id)!));
    }

    private static ApprovalsController ControllerFor(FakeInvoiceRepository repository, UserSession session)
    {
        var controller = new ApprovalsController(new ApprovalService(repository));
        var httpContext = new DefaultHttpContext();
        httpContext.Items[HttpContextExtensions.SessionKey] = session;
        controller.ControllerContext = new ControllerContext { HttpContext = httpContext };
        return controller;
    }

    private static Invoice PendingInvoice(decimal amount) =>
        new() { Id = "INV-1", CustomerName = "Test School", Amount = amount, Status = InvoiceStatus.PendingApproval };

    private static string? ErrorMessage(object? value) =>
        value?.GetType().GetProperty("error")?.GetValue(value) as string;

    private static InvoiceSnapshot Snapshot(Invoice invoice) =>
        new(
            invoice.Id,
            invoice.CustomerName,
            invoice.Amount,
            invoice.Status,
            invoice.CreatedAt,
            invoice.DecidedBy,
            invoice.DecidedAt,
            invoice.DecisionNote);

    private sealed record InvoiceSnapshot(
        string Id,
        string CustomerName,
        decimal Amount,
        InvoiceStatus Status,
        DateTime CreatedAt,
        string? DecidedBy,
        DateTime? DecidedAt,
        string? DecisionNote);
}

