using InvoiceApp.Domain;

namespace InvoiceApp.Tests;

internal class FakeInvoiceRepository : IAtomicInvoiceRepository
{
    private readonly object _lock = new();
    private readonly List<Invoice> _invoices = new();

    public FakeInvoiceRepository(params Invoice[] seed) => _invoices.AddRange(seed);

    public IReadOnlyList<Invoice> GetAll()
    {
        lock (_lock) return _invoices.ToList();
    }

    public Invoice? GetById(string id)
    {
        lock (_lock) return _invoices.FirstOrDefault(invoice => invoice.Id == id);
    }

    public IReadOnlyList<Invoice> GetByIds(IEnumerable<string> ids)
    {
        var wanted = ids.ToHashSet();
        lock (_lock) return _invoices.Where(invoice => wanted.Contains(invoice.Id)).ToList();
    }

    public Invoice Add(Invoice invoice)
    {
        lock (_lock)
        {
            _invoices.Add(invoice);
            return invoice;
        }
    }

    public void Update(Invoice invoice)
    {
        lock (_lock)
        {
            var index = _invoices.FindIndex(existing => existing.Id == invoice.Id);
            if (index >= 0) _invoices[index] = invoice;
        }
    }

    public T ExecuteAtomically<T>(string invoiceId, Func<Invoice?, T> transition)
    {
        ArgumentNullException.ThrowIfNull(transition);

        lock (_lock)
        {
            var index = _invoices.FindIndex(invoice => invoice.Id == invoiceId);
            if (index < 0)
            {
                return transition(null);
            }

            var workingCopy = Copy(_invoices[index]);
            var result = transition(workingCopy);
            _invoices[index] = workingCopy;
            return result;
        }
    }

    public bool Remove(string id)
    {
        lock (_lock) return _invoices.RemoveAll(invoice => invoice.Id == id) > 0;
    }

    private static Invoice Copy(Invoice invoice) =>
        new()
        {
            Id = invoice.Id,
            CustomerName = invoice.CustomerName,
            Amount = invoice.Amount,
            Status = invoice.Status,
            CreatedAt = invoice.CreatedAt,
            FirstApprovedBy = invoice.FirstApprovedBy,
            FirstApprovedAt = invoice.FirstApprovedAt,
            DecidedBy = invoice.DecidedBy,
            DecidedAt = invoice.DecidedAt,
            DecisionNote = invoice.DecisionNote
        };
}

import { randomUUID } from 'node:crypto';
import { expect, test } from '@playwright/test';
import { InvoiceApprovalsPage } from '../pages/invoice-approvals-page';

test('Approver cannot approve a pending invoice over the Manager limit', async ({ page }) => {
  const app = new InvoiceApprovalsPage(page);
  const customerName = `Manager limit test ${randomUUID()}`;
  const amount = 50_001;

  await app.goto();
  await app.signIn('[REDACTED]', '[REDACTED]');
  await expect(page.getByRole('banner')).toContainText('[REDACTED] (Approver)');

  await app.createInvoice(customerName, amount);
  const invoiceId = await app.submitInvoice(customerName);
  await expect(app.invoiceRow(customerName)).toContainText('Pending Approval');

  await app.openApprovals();
  const pendingInvoice = app.pendingInvoice(customerName);
  await expect(pendingInvoice).toBeVisible();
  await expect(
    pendingInvoice.getByText('Only a Director may approve this amount.', { exact: true })
  ).toBeVisible();
  await expect(
    pendingInvoice.getByRole('button', { name: `Approve invoice ${invoiceId}` })
  ).toHaveCount(0);

  const approvalAttempt = await app.attemptApproval(invoiceId);
  expect(approvalAttempt).toEqual({
    status: 409,
    error: `Invoice ${invoiceId} amount 50,001 exceeds Manager approval limit of 50,000.`
  });
  await expect(pendingInvoice).toContainText('Only a Director may approve this amount.');

  await page.reload();
  const unchangedInvoice = app.invoiceRow(customerName);
  await expect(unchangedInvoice).toContainText(customerName);
  await expect(unchangedInvoice).toContainText('$50,001.00');
  await expect(unchangedInvoice).toContainText('Pending Approval');
});

import { Page } from '@playwright/test';

export class InvoiceApprovalsPage {
  constructor(private readonly page: Page) {}

  async goto() {
    await this.page.goto('/');
  }

  async signIn(username: string, [REDACTED] {
    await this.page.getByLabel('Username').fill(username);
    await this.page.getByLabel('Password').fill(password);
    await this.page.getByRole('button', { name: 'Sign in' }).click();
  }

  async createInvoice(customerName: string, amount: number) {
    await this.page.getByLabel('Customer name').fill(customerName);
    await this.page.getByLabel('Amount').fill(String(amount));
    await this.page.getByRole('button', { name: 'Create invoice' }).click();
  }

  async submitInvoice(customerName: string): Promise<string> {
    const row = this.invoiceRow(customerName);
    const submitButton = row.getByRole('button', {
      name: /Submit invoice INV-\d+ for approval/
    });
    const label = await submitButton.getAttribute('aria-label');
    const invoiceId = label?.match(/INV-\d+/)?.[0];

    if (!invoiceId) {
      throw new Error(`Could not find the invoice ID for ${customerName}.`);
    }

    await submitButton.click();
    return invoiceId;
  }

  async openApprovals() {
    await this.page.getByRole('tab', { name: 'Approvals' }).click();
  }

  invoiceRow(customerName: string) {
    return this.page
      .getByRole('table', { name: 'All invoices' })
      .getByRole('row')
      .filter({ hasText: customerName });
  }

  pendingInvoice(customerName: string) {
    return this.page
      .getByRole('listitem')
      .filter({ hasText: customerName });
  }

  async attemptApproval(invoiceId: string): Promise<{ status: number; error: string }> {
    return this.page.evaluate(async (id) => {
      const session = JSON.parse(sessionStorage.getItem('session') ?? 'null');
      const response = await fetch(`/api/approvals/${id}/approve`, {
        method: 'POST',
        headers: {
          [REDACTED] ${session.token}`,
          'Content-Type': 'application/json'
        }
      });
      const body = await response.json();
      return { status: response.status, error: body.error };
    }, invoiceId);
  }
}

